<section class="rv-home"><div class="rv-page-heading"><div><p class="rv-eyebrow">REPORTE DE HORAS</p><h1>El trabajo, en su fecha.</h1><p>Zona America/Bogota. Fechas inclusivas; las sesiones que cruzan medianoche se recortan al intervalo seleccionado.</p></div></div>
<?php if ($error): ?><p class="alert alert-error" role="alert"><?= $this->text->e($error) ?></p><?php endif ?>
<article class="rv-panel"><form class="rv-entry-form" method="get" action="<?= $this->url->dir() ?>"><input type="hidden" name="controller" value="RvReportController"><input type="hidden" name="action" value="show"><input type="hidden" name="plugin" value="RvSoftware"><label>Desde<input type="date" name="from" value="<?= $this->text->e($values['from']) ?>" required></label><label>Hasta<input type="date" name="until" value="<?= $this->text->e($values['until']) ?>" required></label>
<?php foreach (array('project_id'=>'Proyecto','user_id'=>'Usuario','client_id'=>'Cliente','bag_id'=>'Bolsa') as $key=>$label): ?><?php if ($choices[$key]): ?><label><?= $label ?><select name="<?= $key ?>"><option value="">Todos los permitidos</option><?php foreach ($choices[$key] as $id=>$name): ?><option value="<?= (int)$id ?>" <?= (string)$values[$key] === (string)$id ? 'selected' : '' ?>><?= $this->text->e($name) ?></option><?php endforeach ?></select></label><?php endif ?><?php endforeach ?>
<label>Estado<select name="status"><option value="">Todos</option><?php foreach (array('pending'=>'Pendiente','approved'=>'Aprobado') as $key=>$label): ?><option value="<?= $key ?>" <?= $values['status'] === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach ?></select></label><label>Clasificación<select name="billable"><option value="">Todas</option><option value="1" <?= $values['billable'] === '1' ? 'selected' : '' ?>>Facturable</option><option value="0" <?= $values['billable'] === '0' ? 'selected' : '' ?>>No facturable</option></select></label><button class="btn btn-blue">Consultar</button><button class="btn" name="format" value="csv">Descargar CSV</button></form></article>
<?php if ($report): ?><div class="rv-metrics"><?php foreach (array('worked_seconds'=>'Trabajado','billable_seconds'=>'Clasificado facturable','approved_seconds'=>'Aprobado','consumed_seconds'=>'Consumido conciliado') as $key=>$label): ?><article class="rv-panel"><h2><?= $label ?></h2><p><strong><?= $this->text->e(number_format($report['totals'][$key]/3600,2,',','.')) ?> h</strong> · <?= (int)$report['totals'][$key] ?> s</p></article><?php endforeach ?></div><p><?= $this->text->e($report['history_note']) ?></p>
<?php if ($report['totals']['unreconciled_sessions']): ?><p class="alert alert-error" role="alert"><?= (int)$report['totals']['unreconciled_sessions'] ?> sesiones pendientes de conciliación: su consumo no se suma como conciliado. Consulta bolsas y rectifica con motivo.</p><?php endif ?>
<?php if (! $report['rows']): ?><article class="rv-panel"><p>No hay sesiones cerradas visibles en este periodo.</p></article><?php endif ?>
<?php foreach ($report['rows'] as $row): ?><article class="rv-panel"><h2><?= $this->text->e($row['project_name'].' / '.$row['task_title']) ?></h2><p><?= $this->text->e($row['subtask_title'].' · '.$row['username']) ?> · Sesión #<?= (int)$row['id'] ?> v<?= (int)$row['version'] ?></p><p><?= (new DateTimeImmutable('@'.$row['start']))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d H:i:s') ?> → <?= (new DateTimeImmutable('@'.$row['end']))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d H:i:s') ?></p><p><?= (int)$row['worked_seconds'] ?> s en periodo · <?= $row['status'] === 'approved' ? 'Aprobado' : 'Pendiente' ?> · <?= $row['billable'] === null ? 'Sin clasificar' : ((int)$row['billable'] === 1 ? 'Facturable' : 'No facturable') ?></p><p><?= $this->text->e($row['note']) ?></p><?php if ($row['bag_name']): ?><p><?= $this->text->e($row['client_name'].' / '.$row['bag_name']) ?></p><?php endif ?></article><?php endforeach ?>
<?php endif ?></section>
